const input=$('Receber proposta e evidências').item.json;
const hold=reason=>({json:{post_id:input.post_id,decision:'reter',reason}});
if($json.status!=='completed'||!Array.isArray($json.output))return hold('Avaliação incompleta.');
const parts=$json.output.flatMap(x=>x.content??[]).filter(x=>x.type==='output_text').map(x=>x.text);
let result;
try{result=parts.length===1&&typeof parts[0]==='object'?parts[0]:JSON.parse(parts.join(''));}catch{return hold('Parecer inválido.');}
if(!result||!['recomendar_publicacao','devolver','reter'].includes(result.decision)||typeof result.reason!=='string'||!result.reason.trim()||!Array.isArray(result.blocking_issues)||result.blocking_issues.some(x=>typeof x!=='string'||!x.trim()))return hold('Parecer inválido.');
if (typeof input.title === 'string' && /(?:\s*\(\s*(?:[0-3]?\d[/.–-][01]?\d(?:[/.–-](?:\d{4}|\d{2}))?|\d{4}-\d{2}-\d{2})\s*\)|\s+(?:[—–|-]\s*)?(?:[0-3]?\d[/.–-][01]?\d[/.–-](?:\d{4}|\d{2})|\d{4}-\d{2}-\d{2})|\s*\(\s*[0-3]?\d\s+de\s+(?:janeiro|fevereiro|março|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro)(?:\s+de\s+\d{4})?\s*\))\s*$/iu.test(input.title)) {
  result.blocking_issues.push('Retirar a data avulsa da manchete.');
}
const hasSourceCommentary = value => typeof value==='string' && /(?:^|[.!?]\s+|\n)\s*(?:a\s+(?:reportagem|matéria|publicação|notícia)|o\s+(?:texto|material|briefing))[^.!?\n]{0,130}?\b(?:n[aã]o\s+(?:informa|detalha|explica|especifica|menciona|indica|esclarece|traz|apresenta|fornece|diz|teve acesso|revela)|omite)\b/iu.test(value.replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' '));
if ([input.title,input.excerpt,input.content].some(hasSourceCommentary)) {
  result.blocking_issues.push('Retirar do texto público os comentários sobre o que a reportagem de origem não informa. Manter o fato sustentado e registrar a lacuna útil no parecer interno.');
}
if(result.decision==='recomendar_publicacao'&&result.blocking_issues.length)result.decision='devolver';
return {json:{post_id:input.post_id,...result,proposal:{title:input.title,excerpt:input.excerpt,content:input.content,changes:input.changes,pending:input.pending}}};
